/// <summary>
/// Contract class for sales order picking list generation
/// </summary>
[DataContractAttribute]
class METPickDirectorDataContract extends METSysOperationTaskDataContract
{
    List soList;
    guid topPickingProcessId;

}

Method.Source:
/// <summary>
/// Get/set the top picking process guid id
/// </summary>
/// <param name = "_topPickingProcessId">Top picking process guid id</param>
/// <returns>Top picking process guid id</returns>
[DataMember, SysOperationControlVisibilityAttribute(false)]
public guid parmTopPickingProcessId(guid _topPickingProcessId = topPickingProcessId)
{
    topPickingProcessId = _topPickingProcessId;

    return topPickingProcessId;
}

/// <summary>
/// Gets and sets the sales order id listy.
/// </summary>
/// <param name = "_soList">_soList</param>
/// <returns>List</returns>
[DataMember,
    AifCollectionType('_soList', Types::String, extendedTypeStr(SalesIdBase)),
    SysOperationControlVisibilityAttribute(false)]
public List parmSalesIdList(List _soList = soList)
{
    soList = _soList;

    return soList;
}
